// Fixed-ratio 640x512 -> 720x576 Catmull-Rom bicubic scaler.
//
// The ratio is exactly 9/8 in both directions, so coordinates and fractional
// phases are generated by accumulators. No run-time divider or vendor divider
// IP is required. Y, Cb and Cr are filtered independently to preserve YUV422.
module BicubicScaler640x512 (
    input  wire        clk,
    input  wire        reset,

    input  wire [7:0]  in_y,
    input  wire [7:0]  in_c,
    input  wire        in_valid,
    input  wire        in_sof,
    input  wire        in_eol,
    output wire        in_ready,

    output reg  [7:0]  out_y,
    output reg  [7:0]  out_c,
    output reg         out_valid,
    output wire        out_sof,
    output wire        out_eol,
    input  wire        out_ready,

    output reg         frame_done,
    output reg         stream_error,
    output reg [15:0]  input_frame_count,
    output reg [15:0]  output_frame_count,
    output reg [15:0]  dropped_frame_count
);
    localparam [3:0] S_SYNC  = 4'd0;
    localparam [3:0] S_LOAD  = 4'd1;
    localparam [3:0] S_CHECK = 4'd2;
    localparam [3:0] S_RD0   = 4'd3;
    localparam [3:0] S_RD1   = 4'd4;
    localparam [3:0] S_RD2   = 4'd5;
    localparam [3:0] S_RD3   = 4'd6;
    localparam [3:0] S_RD4   = 4'd7;
    localparam [3:0] S_H     = 4'd8;
    localparam [3:0] S_V     = 4'd9;
    localparam [3:0] S_OUT   = 4'd10;

    reg [3:0] state;
    reg [9:0] src_x;
    reg [9:0] src_y;
    reg [9:0] loaded_y;
    reg       loaded_valid;
    reg       input_frame_done;
    reg       input_capture;

    reg [9:0] out_x;
    reg [9:0] out_y_count;
    reg [9:0] base_x;
    reg [8:0] base_cx;
    reg [9:0] base_y;
    reg [3:0] phase_x;
    reg [3:0] phase_cx;
    reg [3:0] phase_y;

    reg [9:0] rd_y_addr;
    reg [8:0] rd_c_addr;

    // Four circular source-line banks. Chroma is stored as two 320-sample
    // component planes so cubic interpolation never mixes Cb with Cr.
    reg [7:0] ym0 [0:639]; reg [7:0] ym1 [0:639];
    reg [7:0] ym2 [0:639]; reg [7:0] ym3 [0:639];
    reg [7:0] cb0 [0:319]; reg [7:0] cb1 [0:319];
    reg [7:0] cb2 [0:319]; reg [7:0] cb3 [0:319];
    reg [7:0] cr0 [0:319]; reg [7:0] cr1 [0:319];
    reg [7:0] cr2 [0:319]; reg [7:0] cr3 [0:319];

    reg [7:0] qy0, qy1, qy2, qy3;
    reg [7:0] qcb0, qcb1, qcb2, qcb3;
    reg [7:0] qcr0, qcr1, qcr2, qcr3;

    reg [7:0] my0[0:3], my1[0:3], my2[0:3], my3[0:3];
    reg [7:0] mc0[0:3], mc1[0:3], mc2[0:3], mc3[0:3];

    reg signed [19:0] hy0, hy1, hy2, hy3;
    reg signed [19:0] hc0, hc1, hc2, hc3;
    reg signed [31:0] sum_y;
    reg signed [31:0] sum_c;

    wire in_take = in_valid && in_ready;
    // Always drain the clock-crossing FIFO.  A selected source frame is
    // written into the four-line ring while the preceding lines are scaled;
    // intervening frames are deliberately discarded until S_SYNC.
    assign in_ready = 1'b1;
    assign out_sof = out_valid && (out_x == 10'd0) &&
                     (out_y_count == 10'd0);
    assign out_eol = out_valid && (out_x == 10'd719);

    function signed [9:0] coeff;
        input [3:0] phase;
        input [1:0] tap;
        begin
            case (phase)
                4'd0: case(tap) 0:coeff=0;   1:coeff=256; 2:coeff=0;   default:coeff=0;   endcase
                4'd1: case(tap) 0:coeff=-11; 1:coeff=248; 2:coeff=20;  default:coeff=-1;  endcase
                4'd2: case(tap) 0:coeff=-17; 1:coeff=228; 2:coeff=50;  default:coeff=-5;  endcase
                4'd3: case(tap) 0:coeff=-19; 1:coeff=199; 2:coeff=85;  default:coeff=-9;  endcase
                4'd4: case(tap) 0:coeff=-18; 1:coeff=164; 2:coeff=124; default:coeff=-14; endcase
                4'd5: case(tap) 0:coeff=-14; 1:coeff=125; 2:coeff=163; default:coeff=-18; endcase
                4'd6: case(tap) 0:coeff=-9;  1:coeff=85;  2:coeff=199; default:coeff=-19; endcase
                4'd7: case(tap) 0:coeff=-5;  1:coeff=49;  2:coeff=229; default:coeff=-17; endcase
                default: case(tap) 0:coeff=-1; 1:coeff=19; 2:coeff=249; default:coeff=-11; endcase
            endcase
        end
    endfunction

    function [9:0] clamp_x;
        input signed [11:0] x;
        begin
            if (x < 0) clamp_x = 0;
            else if (x > 639) clamp_x = 639;
            else clamp_x = x[9:0];
        end
    endfunction
    function [8:0] clamp_cx;
        input signed [10:0] x;
        begin
            if (x < 0) clamp_cx = 0;
            else if (x > 319) clamp_cx = 319;
            else clamp_cx = x[8:0];
        end
    endfunction
    function [9:0] clamp_sy;
        input signed [11:0] y;
        begin
            if (y < 0) clamp_sy = 0;
            else if (y > 511) clamp_sy = 511;
            else clamp_sy = y[9:0];
        end
    endfunction
    function [7:0] clip8;
        input signed [31:0] value;
        reg signed [31:0] shifted;
        begin
            shifted = value >>> 16;
            if (shifted < 0) clip8 = 0;
            else if (shifted > 255) clip8 = 8'hff;
            else clip8 = shifted[7:0];
        end
    endfunction

    // Explicit edge replication avoids signed-width ambiguity at coordinate 0.
    wire [9:0] ry0 = (base_y == 0) ? 10'd0 : base_y - 1'b1;
    wire [9:0] ry1 = base_y;
    wire [9:0] ry2 = (base_y >= 511) ? 10'd511 : base_y + 1'b1;
    wire [9:0] ry3 = (base_y >= 510) ? 10'd511 : base_y + 2'd2;

    wire [7:0] tap_y0 = (ry0[1:0]==0)?qy0:(ry0[1:0]==1)?qy1:(ry0[1:0]==2)?qy2:qy3;
    wire [7:0] tap_y1 = (ry1[1:0]==0)?qy0:(ry1[1:0]==1)?qy1:(ry1[1:0]==2)?qy2:qy3;
    wire [7:0] tap_y2 = (ry2[1:0]==0)?qy0:(ry2[1:0]==1)?qy1:(ry2[1:0]==2)?qy2:qy3;
    wire [7:0] tap_y3 = (ry3[1:0]==0)?qy0:(ry3[1:0]==1)?qy1:(ry3[1:0]==2)?qy2:qy3;
    wire [7:0] tap_cb0= (ry0[1:0]==0)?qcb0:(ry0[1:0]==1)?qcb1:(ry0[1:0]==2)?qcb2:qcb3;
    wire [7:0] tap_cb1= (ry1[1:0]==0)?qcb0:(ry1[1:0]==1)?qcb1:(ry1[1:0]==2)?qcb2:qcb3;
    wire [7:0] tap_cb2= (ry2[1:0]==0)?qcb0:(ry2[1:0]==1)?qcb1:(ry2[1:0]==2)?qcb2:qcb3;
    wire [7:0] tap_cb3= (ry3[1:0]==0)?qcb0:(ry3[1:0]==1)?qcb1:(ry3[1:0]==2)?qcb2:qcb3;
    wire [7:0] tap_cr0= (ry0[1:0]==0)?qcr0:(ry0[1:0]==1)?qcr1:(ry0[1:0]==2)?qcr2:qcr3;
    wire [7:0] tap_cr1= (ry1[1:0]==0)?qcr0:(ry1[1:0]==1)?qcr1:(ry1[1:0]==2)?qcr2:qcr3;
    wire [7:0] tap_cr2= (ry2[1:0]==0)?qcr0:(ry2[1:0]==1)?qcr1:(ry2[1:0]==2)?qcr2:qcr3;
    wire [7:0] tap_cr3= (ry3[1:0]==0)?qcr0:(ry3[1:0]==1)?qcr1:(ry3[1:0]==2)?qcr2:qcr3;
    wire [7:0] tap_c0 = out_x[0] ? tap_cr0 : tap_cb0;
    wire [7:0] tap_c1 = out_x[0] ? tap_cr1 : tap_cb1;
    wire [7:0] tap_c2 = out_x[0] ? tap_cr2 : tap_cb2;
    wire [7:0] tap_c3 = out_x[0] ? tap_cr3 : tap_cb3;

    // Synchronous RAM reads and writes.
    always @(posedge clk) begin
        qy0 <= ym0[rd_y_addr]; qy1 <= ym1[rd_y_addr];
        qy2 <= ym2[rd_y_addr]; qy3 <= ym3[rd_y_addr];
        qcb0 <= cb0[rd_c_addr]; qcb1 <= cb1[rd_c_addr];
        qcb2 <= cb2[rd_c_addr]; qcb3 <= cb3[rd_c_addr];
        qcr0 <= cr0[rd_c_addr]; qcr1 <= cr1[rd_c_addr];
        qcr2 <= cr2[rd_c_addr]; qcr3 <= cr3[rd_c_addr];
        if (in_take && (input_capture || ((state == S_SYNC) && in_sof))) begin
            case (src_y[1:0])
                2'd0: begin
                    ym0[src_x] <= in_y;
                    if (!src_x[0]) cb0[src_x[9:1]] <= in_c; else cr0[src_x[9:1]] <= in_c;
                end
                2'd1: begin
                    ym1[src_x] <= in_y;
                    if (!src_x[0]) cb1[src_x[9:1]] <= in_c; else cr1[src_x[9:1]] <= in_c;
                end
                2'd2: begin
                    ym2[src_x] <= in_y;
                    if (!src_x[0]) cb2[src_x[9:1]] <= in_c; else cr2[src_x[9:1]] <= in_c;
                end
                default: begin
                    ym3[src_x] <= in_y;
                    if (!src_x[0]) cb3[src_x[9:1]] <= in_c; else cr3[src_x[9:1]] <= in_c;
                end
            endcase
        end
    end

    integer k;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state            <= S_SYNC;
            src_x            <= 0; src_y <= 0; loaded_y <= 0;
            loaded_valid     <= 1'b0;
            input_frame_done <= 1'b0;
            input_capture    <= 1'b0;
            out_x            <= 0; out_y_count <= 0;
            base_x           <= 0; base_cx <= 0; base_y <= 0;
            phase_x          <= 0; phase_cx <= 0; phase_y <= 0;
            rd_y_addr        <= 0; rd_c_addr <= 0;
            out_y            <= 0; out_c <= 8'h80; out_valid <= 1'b0;
            frame_done       <= 1'b0;
            stream_error     <= 1'b0;
            input_frame_count  <= 16'd0;
            output_frame_count <= 16'd0;
            dropped_frame_count<= 16'd0;
            sum_y            <= 0; sum_c <= 0;
        end else begin
            frame_done <= 1'b0;

            // Count every source SOF, every completed scaled frame and any
            // source frame that arrives while this core is not ready to begin
            // a new capture.  At 160 MHz dropped_frame_count must stay zero.
            if (in_take && in_sof) begin
                input_frame_count <= input_frame_count + 1'b1;
                if (!((state == S_SYNC) && !input_capture))
                    dropped_frame_count <= dropped_frame_count + 1'b1;
            end

            // Input loading runs independently of the interpolation FSM.
            // At 160 MHz one 640-pixel source line can be
            // stored while the previous 720-pixel output line is calculated.
            if (in_take) begin
                if ((state == S_SYNC) && in_sof) begin
                    input_capture    <= 1'b1;
                    input_frame_done <= 1'b0;
                    loaded_valid     <= 1'b0;
                    src_x            <= 10'd1;
                    src_y            <= 10'd0;
                end else if (input_capture) begin
                    if (in_sof) begin
                        stream_error <= 1'b1;
                        input_capture <= 1'b0;
                    end else if (in_eol) begin
                        if (src_x != 10'd639)
                            stream_error <= 1'b1;
                        loaded_y     <= src_y;
                        loaded_valid <= 1'b1;
                        src_x        <= 0;
                        if (src_y == 10'd511) begin
                            input_frame_done <= 1'b1;
                            input_capture    <= 1'b0;
                        end else begin
                            src_y <= src_y + 1'b1;
                        end
                    end else if (src_x == 10'd639) begin
                        stream_error <= 1'b1;
                        input_capture <= 1'b0;
                    end else begin
                        src_x <= src_x + 1'b1;
                    end
                end
            end

            case (state)
                S_SYNC: begin
                    out_valid <= 1'b0;
                    out_x <= 0; out_y_count <= 0;
                    base_x <= 0; base_cx <= 0; base_y <= 0;
                    phase_x <= 0; phase_cx <= 0; phase_y <= 0;
                    if (in_take && in_sof) begin
                        state <= S_CHECK;
                    end
                end

                S_LOAD: begin
                    state <= S_CHECK;
                end

                S_CHECK: begin
                    out_valid <= 1'b0;
                    if (loaded_valid &&
                        (((base_y >= 510 ? 10'd511 : base_y + 2'd2) <= loaded_y) ||
                         input_frame_done)) begin
                        out_x   <= 0;
                        base_x  <= 0;
                        base_cx <= 0;
                        phase_x <= 0;
                        phase_cx<= 0;
                        state   <= S_RD0;
                    end else begin
                        state <= S_CHECK;
                    end
                end

                S_RD0: begin
                    rd_y_addr <= (base_x == 0) ? 10'd0 : base_x - 1'b1;
                    rd_c_addr <= (base_cx == 0) ? 9'd0 : base_cx - 1'b1;
                    state <= S_RD1;
                end
                S_RD1: begin
                    rd_y_addr <= clamp_x($signed({1'b0,base_x}));
                    rd_c_addr <= clamp_cx($signed({1'b0,base_cx}));
                    state <= S_RD2;
                end
                S_RD2: begin
                    my0[0]<=tap_y0; my1[0]<=tap_y1; my2[0]<=tap_y2; my3[0]<=tap_y3;
                    mc0[0]<=tap_c0; mc1[0]<=tap_c1; mc2[0]<=tap_c2; mc3[0]<=tap_c3;
                    rd_y_addr <= (base_x >= 639) ? 10'd639 : base_x + 1'b1;
                    rd_c_addr <= (base_cx >= 319) ? 9'd319 : base_cx + 1'b1;
                    state <= S_RD3;
                end
                S_RD3: begin
                    my0[1]<=tap_y0; my1[1]<=tap_y1; my2[1]<=tap_y2; my3[1]<=tap_y3;
                    mc0[1]<=tap_c0; mc1[1]<=tap_c1; mc2[1]<=tap_c2; mc3[1]<=tap_c3;
                    rd_y_addr <= (base_x >= 638) ? 10'd639 : base_x + 2'd2;
                    rd_c_addr <= (base_cx >= 318) ? 9'd319 : base_cx + 2'd2;
                    state <= S_RD4;
                end
                S_RD4: begin
                    my0[2]<=tap_y0; my1[2]<=tap_y1; my2[2]<=tap_y2; my3[2]<=tap_y3;
                    mc0[2]<=tap_c0; mc1[2]<=tap_c1; mc2[2]<=tap_c2; mc3[2]<=tap_c3;
                    state <= S_H;
                end
                S_H: begin
                    my0[3]<=tap_y0; my1[3]<=tap_y1; my2[3]<=tap_y2; my3[3]<=tap_y3;
                    mc0[3]<=tap_c0; mc1[3]<=tap_c1; mc2[3]<=tap_c2; mc3[3]<=tap_c3;
                    // Column 3 is taken directly from the current RAM output;
                    // columns 0..2 are the registered earlier reads.
                    hy0 <= $signed({1'b0,my0[0]})*coeff(phase_x,0) + $signed({1'b0,my0[1]})*coeff(phase_x,1) +
                           $signed({1'b0,my0[2]})*coeff(phase_x,2) + $signed({1'b0,tap_y0})*coeff(phase_x,3);
                    hy1 <= $signed({1'b0,my1[0]})*coeff(phase_x,0) + $signed({1'b0,my1[1]})*coeff(phase_x,1) +
                           $signed({1'b0,my1[2]})*coeff(phase_x,2) + $signed({1'b0,tap_y1})*coeff(phase_x,3);
                    hy2 <= $signed({1'b0,my2[0]})*coeff(phase_x,0) + $signed({1'b0,my2[1]})*coeff(phase_x,1) +
                           $signed({1'b0,my2[2]})*coeff(phase_x,2) + $signed({1'b0,tap_y2})*coeff(phase_x,3);
                    hy3 <= $signed({1'b0,my3[0]})*coeff(phase_x,0) + $signed({1'b0,my3[1]})*coeff(phase_x,1) +
                           $signed({1'b0,my3[2]})*coeff(phase_x,2) + $signed({1'b0,tap_y3})*coeff(phase_x,3);
                    hc0 <= $signed({1'b0,mc0[0]})*coeff(phase_cx,0) + $signed({1'b0,mc0[1]})*coeff(phase_cx,1) +
                           $signed({1'b0,mc0[2]})*coeff(phase_cx,2) + $signed({1'b0,tap_c0})*coeff(phase_cx,3);
                    hc1 <= $signed({1'b0,mc1[0]})*coeff(phase_cx,0) + $signed({1'b0,mc1[1]})*coeff(phase_cx,1) +
                           $signed({1'b0,mc1[2]})*coeff(phase_cx,2) + $signed({1'b0,tap_c1})*coeff(phase_cx,3);
                    hc2 <= $signed({1'b0,mc2[0]})*coeff(phase_cx,0) + $signed({1'b0,mc2[1]})*coeff(phase_cx,1) +
                           $signed({1'b0,mc2[2]})*coeff(phase_cx,2) + $signed({1'b0,tap_c2})*coeff(phase_cx,3);
                    hc3 <= $signed({1'b0,mc3[0]})*coeff(phase_cx,0) + $signed({1'b0,mc3[1]})*coeff(phase_cx,1) +
                           $signed({1'b0,mc3[2]})*coeff(phase_cx,2) + $signed({1'b0,tap_c3})*coeff(phase_cx,3);
                    state <= S_V;
                end
                S_V: begin
                    out_y <= clip8(hy0*coeff(phase_y,0) + hy1*coeff(phase_y,1) +
                                   hy2*coeff(phase_y,2) + hy3*coeff(phase_y,3));
                    out_c <= clip8(hc0*coeff(phase_y,0) + hc1*coeff(phase_y,1) +
                                   hc2*coeff(phase_y,2) + hc3*coeff(phase_y,3));
                    out_valid <= 1'b1;
                    state <= S_OUT;
                end
                S_OUT: begin
                    if (out_ready) begin
                        out_valid <= 1'b0;
                        if (out_x == 10'd719) begin
                            if (out_y_count == 10'd575) begin
                                frame_done <= 1'b1;
                                output_frame_count <= output_frame_count + 1'b1;
                                state <= S_SYNC;
                            end else begin
                                out_y_count <= out_y_count + 1'b1;
                                if (phase_y + 8 >= 9) begin
                                    phase_y <= phase_y + 8 - 9;
                                    base_y  <= base_y + 1'b1;
                                end else begin
                                    phase_y <= phase_y + 8;
                                end
                                state <= S_CHECK;
                            end
                        end else begin
                            out_x <= out_x + 1'b1;
                            if (phase_x + 8 >= 9) begin
                                phase_x <= phase_x + 8 - 9;
                                base_x  <= base_x + 1'b1;
                            end else phase_x <= phase_x + 8;
                            if (out_x[0]) begin
                                if (phase_cx + 8 >= 9) begin
                                    phase_cx <= phase_cx + 8 - 9;
                                    base_cx  <= base_cx + 1'b1;
                                end else phase_cx <= phase_cx + 8;
                            end
                            state <= S_RD0;
                        end
                    end
                end
                default: state <= S_SYNC;
            endcase
        end
    end
endmodule
